from __future__ import annotations

import base64
from functools import lru_cache
from typing import Any

from ... import __version__ as SYNAPSE_VERSION
from ..paths import SYNAPSE_ROOT


REPORT_BANNER_PATH = SYNAPSE_ROOT / "assets" / "Offensive-Synapse-Banner-Report.jpg"
BANNER_PATH = SYNAPSE_ROOT / "assets" / "Offensive-Synapse-Banner.png"
# The report hero uses the darker, blue-toned "docs" brand banner (optimized JPEG),
# which sits more harmonically over the navy report body than the red console banner.
DOCS_BANNER_PATH = SYNAPSE_ROOT / "assets" / "Synapse-Docs-Banner.jpg"
MODE_TOGGLE_SCRIPT = (
    "function setMode(mode){var high=mode==='high-level';document.body.classList.toggle('operator',!high);"
    "document.body.classList.toggle('high-level',high);var op=document.getElementById('btnOp');var hi=document.getElementById('btnHigh');"
    "if(op){op.setAttribute('aria-pressed',String(!high));}if(hi){hi.setAttribute('aria-pressed',String(high));}"
    "var name=document.getElementById('reportName');if(name){name.textContent=high?'High-Level Report':'Operator Report';}"
    "var badge=document.getElementById('modeBadge');if(badge){badge.textContent=high?'Internal Summary':'Internal Operational Report';}"
    "var bn=document.getElementById('bannerNote');if(bn){var l=bn.querySelector('.line');var s=bn.querySelector('.sub');if(l){l.textContent=high?'internal summary':'internal operator report';}if(s){s.textContent=high?'not a client deliverable \\u00b7 reduced operational noise':'not a client deliverable \\u00b7 contains live values';}}"
    "var note=document.getElementById('footNote');if(note){note.textContent=high?'High-level view - internal summary with reduced operational noise. Source of truth: workspace state and evidence.':'Operator report - internal references included. Source of truth: workspace state and evidence.';}}"
)


@lru_cache(maxsize=1)
def banner_data_uri() -> str:
    for path, mime_type in ((REPORT_BANNER_PATH, "image/jpeg"), (BANNER_PATH, "image/png")):
        try:
            data = path.read_bytes()
        except OSError:
            continue
        return f"data:{mime_type};base64," + base64.b64encode(data).decode("ascii")
    return ""


@lru_cache(maxsize=1)
def docs_banner_data_uri() -> str:
    for path, mime_type in ((DOCS_BANNER_PATH, "image/jpeg"), (REPORT_BANNER_PATH, "image/jpeg"), (BANNER_PATH, "image/png")):
        try:
            data = path.read_bytes()
        except OSError:
            continue
        return f"data:{mime_type};base64," + base64.b64encode(data).decode("ascii")
    return ""


def html_shell(title: Any, body: str, script: str = "", meta: dict[str, Any] | None = None, body_class: str = "operator") -> str:
    combined_script = MODE_TOGGLE_SCRIPT + script
    script_html = f"<script>{combined_script}</script>" if combined_script.strip() else ""
    footer_bits = ["Generated by Synapse"]
    footer_meta = meta or {}
    footer_bits.append(f"v{SYNAPSE_VERSION}")
    if footer_meta.get("workspace"):
        footer_bits.append(f"workspace {footer_meta['workspace']}")
    if footer_meta.get("generated"):
        footer_bits.append(str(footer_meta["generated"]))
    footer_bits.append("authorized engagement use only")
    footer_text = escape_text(" - ".join(footer_bits))
    return (
        "<!doctype html>\n<html><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        f"<title>{escape_text(title)}</title>"
        f"<style>{report_css()}</style>"
        f"{script_html}"
        f"</head><body class=\"{escape_text(body_class)}\">"
        "<!-- CSS hiding in this report is only for internal presentation-density switching. "
        "It is not a security or client-deliverable redaction mechanism. -->"
        f"{body}"
        f'<footer class="synapse-report-footer"><span class="mono">{footer_text}</span>'
        '<span class="footer-note" id="footNote">Operator report - internal references included. '
        "Source of truth: workspace state and evidence.</span></footer>"
        "</body></html>\n"
    )


def banner_html(title: Any, subtitle: Any = "", meta: dict[str, Any] | None = None) -> str:
    meta_items = []
    for key, value in (meta or {}).items():
        if value in ("", None, [], {}):
            continue
        rendered_value = '<span id="reportName">Operator Report</span>' if str(key).lower() == "report" else escape_text(value)
        meta_items.append(f"<span><strong>{escape_label(key)}</strong> {rendered_value}</span>")
    meta_html = "".join(meta_items)
    return (
        '<header class="banner">'
        f'<img class="banner-art" src="{docs_banner_data_uri()}" alt="Synapse - the agentic operations layer for offensive security">'
        '<div class="banner-fade" aria-hidden="true"></div>'
        '<div class="banner-note" id="bannerNote"><span class="line">internal operator report</span>'
        '<span class="sub">not a client deliverable &middot; contains live values</span></div>'
        "</header>"
        '<div class="meta">'
        f"{meta_html}"
        '<span class="spacer"></span>'
        '<span class="mode-badge" id="modeBadge">Internal Operational Report</span>'
        '<div class="switch" role="group" aria-label="Report view">'
        '<button id="btnOp" type="button" aria-pressed="true" onclick="setMode(\'operator\')">Operator</button>'
        '<button id="btnHigh" type="button" aria-pressed="false" onclick="setMode(\'high-level\')">High-Level</button>'
        "</div></div>"
    )


