        "--ink:#e9edf8;--ink-dim:#9aa5c0;--ink-faint:#626d8a;--accent:#5aa6ec;--accent-deep:#3d76b4;--blue:#74b8f2;--blue-deep:#4a8ccc;--red:#ec6055;--green:#56c08e;--amber:#e3a948;"
        "--sev-crit:#ec6055;--sev-high:#ec6055;--sev-med:#e3a948;--sev-low:#74b8f2;--sev-info:#626d8a;--r:12px;--maxw:1680px;"
        # Operator opted into design fonts; system stacks remain as offline fallback.
        "--display:'Oxanium',system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;--body:'IBM Plex Sans',system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;"
        "--mono:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}"
        "*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(1200px 520px at 50% -10%,rgba(90,166,236,.06),transparent 60%),var(--bg);background-attachment:fixed;color:var(--ink);font-family:var(--body);font-size:14px;line-height:1.62;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;font-variant-numeric:tabular-nums}"
        ".wrap{width:100%;max-width:var(--maxw);margin:0 auto;padding:0 32px 96px}.report-strip{width:calc(100% - 64px);max-width:calc(var(--maxw) - 64px);margin:24px auto 0;padding:0}a{color:var(--ink);text-decoration:none}::selection{background:rgba(90,166,236,.28)}"
        # --- Banner -------------------------------------------------------------------
        ".banner{position:relative;width:100%;margin:0;overflow:hidden;border-bottom:1px solid var(--line);background:var(--bg)}.banner-art{display:block;width:100%;height:auto;max-height:clamp(168px,23vw,300px);object-fit:cover;object-position:center}.banner-fade{position:absolute;left:0;right:0;bottom:0;height:84px;background:linear-gradient(to bottom,transparent,var(--bg));pointer-events:none}"
        ".banner-note{position:absolute;right:28px;bottom:16px;z-index:3;display:flex;flex-direction:column;gap:2px;text-align:right;line-height:1.5;font-family:var(--mono);text-shadow:0 1px 10px rgba(0,0,0,.65)}.banner-note .line{font-size:10.5px;color:var(--ink-dim);text-transform:uppercase;letter-spacing:.16em}.banner-note .sub{font-size:10px;color:var(--ink-faint)}body.high-level .banner-note .line{color:var(--blue)}"
        # --- Meta bar + view switch ---------------------------------------------------
        ".meta{width:calc(100% - 64px);max-width:calc(var(--maxw) - 64px);display:flex;flex-wrap:wrap;align-items:center;gap:14px 28px;margin:18px auto 0;padding:17px 20px;background:var(--bg-elev);border:1px solid var(--line);border-radius:var(--r)}.meta span:not(.spacer):not(.mode-badge){display:flex;flex-direction:column;gap:3px}.meta strong{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-faint);font-weight:500}.meta span{font-size:14px;color:var(--ink);font-weight:500}.meta .spacer{flex:1 1 auto}.mode-badge{font-family:var(--display);font-weight:600;letter-spacing:.06em;font-size:12px;text-transform:uppercase;padding:7px 13px;border-radius:999px;border:1px solid var(--accent);color:var(--accent);background:rgba(90,166,236,.08)}body.high-level .mode-badge{border-color:var(--blue);color:var(--blue);background:rgba(87,174,222,.08)}"
        ".switch{display:inline-flex;border:1px solid var(--line);border-radius:999px;padding:3px;background:var(--bg)}.switch button{font-family:var(--display);font-size:12px;font-weight:600;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-dim);background:transparent;border:0;padding:7px 14px;border-radius:999px;cursor:pointer;transition:color .18s}.switch button[aria-pressed=\"true\"]{background:var(--accent);color:#06222a}body.high-level .switch button[aria-pressed=\"true\"]{background:var(--blue);color:#06222a}"
        # --- Risk posture + finding cards --------------------------------------------
