        ".risk-panel{position:relative;background:var(--bg-elev);border:1px solid var(--line);border-radius:var(--r);padding:22px 24px 24px;overflow:hidden}.risk-top{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:18px}.risk-top p{margin:8px 0 0;color:var(--ink-dim);font-family:var(--mono);font-size:12px}.risk-tiles{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.risk-tile{position:relative;background:var(--bg-elev-2);border:1px solid var(--line);border-radius:10px;padding:15px 16px;overflow:hidden}.risk-num{display:block;font-family:var(--display);font-weight:800;font-size:36px;line-height:1;color:var(--ink-faint)}.risk-label{display:flex;align-items:center;gap:7px;margin-top:9px;font-family:var(--mono);font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-faint)}.risk-label:before{content:\"\";width:7px;height:7px;border-radius:50%;background:currentColor}.severity-critical .risk-num,.severity-critical.risk-driver b{color:var(--sev-crit)}.severity-high .risk-num,.severity-high.risk-driver b{color:var(--sev-crit)}.severity-medium .risk-num,.severity-medium.risk-driver b{color:var(--sev-med)}.severity-low .risk-num,.severity-low.risk-driver b{color:var(--sev-low)}.risk-drivers{display:flex;gap:10px 22px;flex-wrap:wrap;margin-top:18px;padding-top:16px;border-top:1px solid var(--line-soft)}.risk-driver{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--ink-dim)}.risk-driver:before{content:\"\";width:8px;height:8px;border-radius:2px;background:var(--blue)}.risk-driver.severity-high:before,.risk-driver.severity-critical:before{background:var(--red)}.risk-driver.severity-medium:before{background:var(--sev-med)}.risk-driver em{font-style:normal;color:var(--ink-faint)}.risk-tile.is-zero .risk-num{color:var(--ink-faint)}"
        ".finding-strip{margin-top:30px}.finding-strip>.section-label{margin-bottom:12px}.finding-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:16px}.finding-card{background:var(--bg-elev);border:1px solid var(--line);border-left:3px solid var(--red);border-radius:10px;padding:18px 20px}.finding-card-top{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px}.finding-card h4{font-size:15.5px;font-weight:650;margin:0 0 8px;color:#f4f7fb;overflow-wrap:anywhere}.finding-card p{margin:0 0 10px;color:var(--ink-dim)}.finding-ref{font-family:var(--mono);font-size:11.5px;color:var(--ink-faint);overflow-wrap:anywhere}"
