        # High-level dossier: the index becomes a flat left-ruled list, not a node timeline.
        "body.high-level .report-toc ol:before{display:none}body.high-level .report-toc li{padding-left:0}body.high-level .report-toc li:before{display:none}body.high-level .report-toc a{border-left:2px solid var(--line);border-radius:0;padding:6px 0 6px 13px;margin-left:0}body.high-level .report-toc a:hover,body.high-level .report-toc a.active{border-left-color:var(--accent);background:transparent;color:var(--ink)}"
